import { Component, OnInit, OnDestroy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Router } from '@angular/router';
import { Observable } from 'rxjs';
import { take } from 'rxjs/operators';
import { AuthService } from '../../core/services/auth.service';
import { AppService, AppState } from '../../core/services/app.service';
import { DashboardStats } from '../../core/models';

@Component({
  selector: 'app-dashboard',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './dashboard.component.html',
  styleUrls: ['./dashboard.component.scss']
})
export class DashboardComponent implements OnInit, OnDestroy {
  appState$: Observable<AppState>;

  constructor(
    private authService: AuthService,
    private appService: AppService,
    private router: Router
  ) {
    this.appState$ = this.appService.appState$;
  }

  ngOnInit(): void {
    // Ensure initial data is loaded once after auth
    this.appService.appState$.pipe(take(1)).subscribe(state => {
      if (!state.dataLoaded) {
        this.appService.loadInitialData().subscribe({
          error: (e) => console.error('Dashboard: initial data load failed', e)
        });
      }
    });

    // Start live auto-refresh (sales) for live stats
    this.appService.startAutoRefresh(10000);
  }

  ngOnDestroy(): void {
    this.appService.stopAutoRefresh();
  }

  getDashboardTitle(): string {
    const user = this.authService.getCurrentUser();
    switch (user?.role) {
      case 'admin': return 'Admin Dashboard';
      case 'sales': return 'Sales Dashboard';
      case 'warehouse': return 'Warehouse Dashboard';
      default: return 'Dashboard';
    }
  }

  getDashboardSubtitle(): string {
    const user = this.authService.getCurrentUser();
    switch (user?.role) {
      case 'admin': return 'Complete Business Overview';
      case 'sales': return 'Track your sales performance';
      case 'warehouse': return 'Inventory & Stock Management';
      default: return 'Business Overview';
    }
  }

  getStats(appState: AppState): DashboardStats {
    const today = new Date();
    const todaySales = appState.sales.filter(sale => {
      const saleDate = new Date(sale.createdAt);
      return saleDate.toDateString() === today.toDateString();
    });

    return {
      totalProducts: appState.products.length,
      lowStockItems: appState.products.filter(p => p.stock <= p.minStock).length,
      todaySales: todaySales.length,
      totalRevenue: appState.sales.reduce((sum, sale) => sum + sale.total, 0),
    };
  }

  navigateTo(route: string): void {
    this.router.navigate([route]);
  }

  getTopCategories(appState: AppState): Array<{ name: string; count: number; color: string }> {
    const counts: Record<string, number> = {};
    appState.sales.forEach(s => s.items.forEach(it => {
      const cat = it.product.category;
      counts[cat] = (counts[cat] || 0) + it.quantity;
    }));
    // Fallback: if no sales, show categories from products with 0
    if (Object.keys(counts).length === 0) {
      appState.products.forEach(p => { counts[p.category] = counts[p.category] || 0; });
    }
    const palette: Record<string, string> = {
      shirts: 'bg-purple-500',
      accessories: 'bg-pink-500',
      pants: 'bg-green-500',
      dresses: 'bg-yellow-500',
      jackets: 'bg-slate-500',
      shoes: 'bg-emerald-500'
    };
    return Object.entries(counts)
      .map(([name, count]) => ({ name, count, color: palette[name] || 'bg-gray-400' }))
      .sort((a, b) => b.count - a.count)
      .slice(0, 4);
  }

  getLowStockProducts(appState: AppState) {
    return appState.products
      .filter(p => p.stock <= p.minStock)
      .sort((a, b) => (a.stock - a.minStock) - (b.stock - b.minStock))
      .slice(0, 3);
  }

  getRecentTransactions(appState: AppState) {
    return [...appState.sales]
      .sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime())
      .slice(0, 3);
  }
}
<div class="dashboard-container" *ngIf="appState$ | async as appState">
  <!-- Dashboard Header -->
  <div class="dashboard-header">
    <div class="header-content">
      <div class="header-text">
        <h1 class="header-title">{{ getDashboardTitle() }}</h1>
        <p class="header-subtitle">Foreign Fits - Global Fashion</p>
        <p class="header-description">{{ getDashboardSubtitle() }}</p>
      </div>
      <div class="header-icon">
        <!-- Decorative icon (non-interactive) -->
        <div class="icon-container">
          <svg class="icon" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z"></path>
            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"></path>
          </svg>
        </div>
      </div>
    </div>
  </div>

  <!-- Section header -->
  <div class="bg-white rounded-xl border border-gray-100 shadow-sm p-4 flex items-center justify-between">
    <div class="text-gray-900 font-semibold">Business Dashboard</div>
    <div class="flex items-center gap-2 text-sm">
      <button class="px-3 py-1.5 rounded-lg bg-gray-900 text-white">Overview</button>
      <button class="px-3 py-1.5 rounded-lg bg-gray-100 text-gray-700 hover:bg-gray-200" (click)="navigateTo('/sales-analytics')">Sales Analytics</button>
    </div>
  </div>

  <!-- Stats Grid -->
  <div class="stats-grid">
    <div class="stat-card cursor-pointer hover:shadow-lg" (click)="navigateTo('/inventory')" (keydown.enter)="navigateTo('/inventory')" role="button" tabindex="0">
      <div class="stat-content">
        <div class="stat-info">
          <p class="stat-label">Total Products</p>
          <p class="stat-value">{{ getStats(appState).totalProducts }}</p>
          <p class="stat-change positive">+12% from last month</p>
        </div>
        <div class="stat-icon blue">
          <svg class="icon" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4"></path>
          </svg>
        </div>
      </div>
    </div>

    <div class="stat-card cursor-pointer hover:shadow-lg" (click)="navigateTo('/sales-history')" (keydown.enter)="navigateTo('/sales-history')" role="button" tabindex="0">
      <div class="stat-content">
        <div class="stat-info">
          <p class="stat-label">Total Revenue</p>
          <p class="stat-value green">₹{{ getStats(appState).totalRevenue.toFixed(2) }}</p>
          <p class="stat-change positive">+8% from last month</p>
        </div>
        <div class="stat-icon green">
          <span class="currency-icon">₹</span>
        </div>
      </div>
    </div>

    <div class="stat-card cursor-pointer hover:shadow-lg" (click)="navigateTo('/sales-history')" (keydown.enter)="navigateTo('/sales-history')" role="button" tabindex="0">
      <div class="stat-content">
        <div class="stat-info">
          <p class="stat-label">Today's Sales</p>
          <p class="stat-value blue">{{ getStats(appState).todaySales }}</p>
          <p class="stat-change info">Transactions today</p>
        </div>
        <div class="stat-icon blue">
          <svg class="icon" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M3 3h2l.4 2M7 13h10l4-8H5.4m0 0L7 13m0 0l-2.293 2.293c-.63.63-.184 1.707.707 1.707H17M17 13v6a2 2 0 01-2 2H9a2 2 0 01-2-2v-6m8 0V9a2 2 0 00-2-2H9a2 2 0 00-2 2v4.01"></path>
          </svg>
        </div>
      </div>
    </div>

    <div class="stat-card cursor-pointer hover:shadow-lg" (click)="navigateTo('/inventory')" (keydown.enter)="navigateTo('/inventory')" role="button" tabindex="0">
      <div class="stat-content">
        <div class="stat-info">
          <p class="stat-label">Low Stock Items</p>
          <p class="stat-value amber">{{ getStats(appState).lowStockItems }}</p>
          <p class="stat-change warning">Needs attention</p>
        </div>
        <div class="stat-icon amber">
          <svg class="icon" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"></path>
          </svg>
        </div>
      </div>
    </div>
  </div>

  <!-- Analytics Cards Row -->
  <div class="grid grid-cols-1 lg:grid-cols-3 gap-6">
    <!-- Top Selling Categories -->
    <div class="bg-white p-6 rounded-xl shadow-md border border-gray-100">
      <div class="flex items-center gap-2 text-gray-900 font-semibold mb-3">
        <svg class="h-5 w-5 text-purple-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 6h16M4 10h16M4 14h16M4 18h16"/></svg>
        <span>Top Selling Categories</span>
      </div>
      <div *ngFor="let c of getTopCategories(appState)" class="flex items-center justify-between py-2 text-sm">
        <div class="flex items-center gap-2">
          <span class="inline-block h-2.5 w-2.5 rounded-full" [ngClass]="c.color"></span>
          <span class="capitalize text-gray-700">{{ c.name }}</span>
        </div>
        <div class="text-gray-900 font-medium">{{ c.count }} sold</div>
      </div>
    </div>

    <!-- Critical Stock Levels -->
    <div class="bg-white p-6 rounded-xl shadow-md border border-gray-100">
      <div class="flex items-center gap-2 text-gray-900 font-semibold mb-3">
        <svg class="h-5 w-5 text-amber-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 9v2m0 4h.01M5.07 19h13.86c1.54 0 2.5-1.67 1.73-3L13.73 5c-.77-1.33-2.7-1.33-3.46 0L3.34 16c-.77 1.33.19 3 1.73 3z"/></svg>
        <span>Critical Stock Levels</span>
      </div>
      <div *ngFor="let p of getLowStockProducts(appState)" class="p-3 mb-2 rounded-lg border border-amber-200 bg-amber-50 text-sm">
        <div class="flex items-center justify-between">
          <div>
            <div class="font-medium text-gray-900 truncate max-w-[220px]">{{ p.name }}</div>
            <div class="text-xs text-gray-600">{{ p.size }} – {{ p.color }}</div>
          </div>
          <div class="text-right">
            <div class="text-amber-600 font-semibold">{{ p.stock }}</div>
            <div class="text-[11px] text-gray-500">Min: {{ p.minStock }}</div>
          </div>
        </div>
      </div>
      <div *ngIf="getLowStockProducts(appState).length === 0" class="text-sm text-gray-500">No critical items.</div>
    </div>

    <!-- Recent Transactions -->
    <div class="bg-white p-6 rounded-xl shadow-md border border-gray-100">
      <div class="flex items-center gap-2 text-gray-900 font-semibold mb-3">
        <svg class="h-5 w-5 text-emerald-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M3 3h2l.4 2M7 13h10l4-8H5.4m0 0L7 13m0 0l-2.293 2.293c-.63.63-.184 1.707.707 1.707H17"/></svg>
        <span>Recent Transactions</span>
      </div>
      <div *ngFor="let s of getRecentTransactions(appState)" class="flex items-center justify-between py-2 text-sm border-b last:border-b-0">
        <div>
          <div class="text-gray-900">Sale #{{ s.id }}</div>
          <div class="text-xs text-gray-500">{{ s.items.length }} item{{ s.items.length > 1 ? 's' : '' }} • {{ s.paymentMethod | uppercase }}</div>
        </div>
        <div class="text-emerald-600 font-semibold">₹{{ s.total | number:'1.2-2' }}</div>
      </div>
      <div *ngIf="getRecentTransactions(appState).length === 0" class="text-sm text-gray-500">No recent sales.</div>
    </div>
  </div>

  <!-- Quick Actions -->
  <div class="quick-actions-card">
    <h3 class="quick-actions-title">Quick Actions</h3>
    <div class="quick-actions-grid">
      <button (click)="navigateTo('/add-product')" class="action-button blue">
        <svg class="action-icon" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4"></path>
        </svg>
        <span class="action-label">Add Product</span>
      </button>

      <button (click)="navigateTo('/sales')" class="action-button green">
        <svg class="action-icon" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M3 3h2l.4 2M7 13h10l4-8H5.4m0 0L7 13m0 0l-2.293 2.293c-.63.63-.184 1.707.707 1.707H17M17 13v6a2 2 0 01-2 2H9a2 2 0 01-2-2v-6m8 0V9a2 2 0 00-2-2H9a2 2 0 00-2 2v4.01"></path>
        </svg>
        <span class="action-label">New Sale</span>
      </button>

      <button (click)="navigateTo('/inventory')" class="action-button orange">
        <svg class="action-icon" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H9.5a2 2 0 01-2-2V5a2 2 0 00-2-2H3"></path>
        </svg>
        <span class="action-label">View Inventory</span>
      </button>

      <button (click)="navigateTo('/sales-history')" class="action-button purple">
        <svg class="action-icon" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z"></path>
        </svg>
        <span class="action-label">View Reports</span>
      </button>
    </div>
  </div>
</div>
